Read the active sheet’s cached values and locate the category header columns and the kms lower/upper range columns in the legend. For each row 7–9, use the category in D and the kms value in C to select the matching legend row and category column. Write the resulting numeric percentages into E7:E9.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = vals.active.title if vals.active is not None else "Current"
vws = vals[sheet_name]
ws = wb[sheet_name]

def to_num(x):
    if isinstance(x, bool):
        return None
    if isinstance(x, (int, float)):
        return float(x)
    if isinstance(x, str):
        try:
            return float(x.strip())
        except Exception:
            return None
    return None

def norm_cat(x):
    if isinstance(x, str):
        s = x.strip().upper()
        if s in {"A", "B", "C", "D", "E"}:
            return s
    return None

# Find the legend header row containing A, B, C, D, E in one row.
cat_cols = {}
for r in range(1, 40):
    cols = {}
    for c in range(1, 40):
        cat = norm_cat(vws.cell(r, c).value)
        if cat:
            cols[cat] = c
    if len(cols) == 5:
        cat_cols = cols
        break

# Fallback to the documented layout: categories in J:N.
if len(cat_cols) < 5:
    cat_cols = {letter: 10 + i for i, letter in enumerate("ABCDE")}

# Find the kms range columns. The first range row should start with 0.
lower_col = None
upper_col = None
for r in range(17, 23):
    nums = []
    for c in range(1, 40):
        n = to_num(vws.cell(r, c).value)
        if n is not None:
            nums.append((c, n))
    if len(nums) >= 2 and abs(nums[0][1]) < 1e-9:
        lower_col = nums[0][0]
        upper_col = nums[1][0]
        break

# Fallback to the documented layout: ranges in H:I.
if lower_col is None or upper_col is None:
    lower_col, upper_col = 8, 9

# Collect legend range rows.
range_rows = []
for r in range(17, 23):
    lo = to_num(vws.cell(r, lower_col).value)
    hi = to_num(vws.cell(r, upper_col).value)
    if lo is not None and hi is not None:
        range_rows.append((r, lo, hi))

def category_from_number(n):
    if n is None:
        return None
    if n <= 59:
        return "A"
    if n <= 99:
        return "B"
    if n <= 139:
        return "C"
    if n <= 179:
        return "D"
    return "E"

results = []
for r in range(7, 10):
    cat = norm_cat(vws.cell(r, 4).value)
    if cat is None:
        cat = category_from_number(to_num(vws.cell(r, 2).value))

    kms = to_num(vws.cell(r, 3).value)
    if cat is None or kms is None:
        ws.cell(r, 5).value = None
        results.append((r, cat, kms, None))
        continue

    chosen = None
    for rr, lo, hi in range_rows:
        if lo <= kms <= hi:
            chosen = (rr, lo, hi)
            break

    # Fallback: use the highest lower bound not exceeding kms.
    if chosen is None:
        best = None
        for rr, lo, hi in range_rows:
            if kms >= lo:
                if best is None or lo > best[1]:
                    best = (rr, lo, hi)
        chosen = best

    if chosen is None:
        ws.cell(r, 5).value = None
        results.append((r, cat, kms, None))
        continue

    rr, lo, hi = chosen
    col = cat_cols.get(cat)
    if col is None and cat in "ABCDE":
        col = upper_col + 1 + "ABCDE".index(cat)

    if col is None:
        ws.cell(r, 5).value = None
        results.append((r, cat, kms, None))
        continue

    val = to_num(vws.cell(rr, col).value)
    ws.cell(r, 5).value = val
    results.append((r, cat, kms, val))

print("sheet:", sheet_name)
print("cat_cols:", cat_cols)
print("lower_col, upper_col:", lower_col, upper_col)
print("range_rows:", range_rows)
print("results:", results)

wb.save(OUT)
